const BASE_URL = (process.env.BASE_URL ?? LOCAL_SERVER_ORIGIN).replace(/\/+$/, "");
const AUTH_TOKEN = resolveAuthToken();
const USER_ID = parseUserIdFromAuthToken(AUTH_TOKEN);
const BROWSER = (process.env.BROWSER ?? "chrome").trim().toLowerCase();
const HEADLESS = probeHeadless(false);
const PUBLIC_IMAGE_AGENT_DEFAULT_SPACE_ID = "01KKY77TT0DA9NY7TNW3R7255N";
const SPACE_ID = (
  process.env.PUBLIC_IMAGE_AGENT_SPACE_ID ?? PUBLIC_IMAGE_AGENT_DEFAULT_SPACE_ID
).trim();
const TIMEOUT_MS = parsePositiveFiniteNumberOrFallback(
  process.env.PUBLIC_IMAGE_AGENT_TIMEOUT_MS,
  180_000,
);
const MIN_BALANCE = parsePositiveFiniteNumberOrFallback(
  process.env.PUBLIC_IMAGE_AGENT_MIN_BALANCE,
  25,
);
const PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL =
  process.env.PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL?.trim() || "";
const SELECTED_SCENARIOS = new Set(
  (process.env.PUBLIC_IMAGE_AGENT_SCENARIOS ?? "")
    .split(",")
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean)
);
const SELECTED_CASES = new Set(
  (process.env.PUBLIC_IMAGE_AGENT_CASES ?? "")
    .split(",")
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean)
);

const PUBLIC_IMAGE_GENERATOR_AGENT_KEY = process.env.PUBLIC_IMAGE_GENERATOR_AGENT_KEY?.trim() || "";
const PUBLIC_IMAGE_EDITOR_AGENT_KEY = process.env.PUBLIC_IMAGE_EDITOR_AGENT_KEY?.trim() || "";
const PUBLIC_IMAGE_CONTINUOUS_AGENT_KEY =
  process.env.PUBLIC_IMAGE_CONTINUOUS_AGENT_KEY?.trim() || "";

const AGENT_TARGETS = [
  {
    slug: "generator" as const,
    name: "GPT Image 2 图片生成器",
    envKey: PUBLIC_IMAGE_GENERATOR_AGENT_KEY,
    expectedWorkflow: "generate",
  },
  {
    slug: "editor" as const,
    name: "GPT Image 2 图片编辑器",
    envKey: PUBLIC_IMAGE_EDITOR_AGENT_KEY,
    expectedWorkflow: "edit",
  },
  {
    slug: "continuous" as const,
    name: "GPT Image 2 连续创作助手",
    envKey: PUBLIC_IMAGE_CONTINUOUS_AGENT_KEY,
    expectedWorkflow: "continuous",
  },
];

const PNG_BLACK = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAGUlEQVR42u3BMQEAAADCoPVP7WENoAAAAG4MIAABITLN7AAAAABJRU5ErkJggg==",
  "base64"
);
const PNG_RED = Buffer.from(
  "",
  "base64"
);
const PNG_GREEN = Buffer.from(
  "",
  "base64"
);
const PNG_MASK = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAM0lEQVR42u3WsQkAAAgDwey/tA5hIcoFvr8yqeUFAADgAiDDAAAAAAAAAO4DPCIAgN+ABq4R8dOefhmCAAAAAElFTkSuQmCC",
  "base64"
);

const VALIDATION_SIGNAL = /validation|error|错误|失败|缺少|缺失|unsupported|不支持|无法/i;
const UPSTREAM_ERROR_SIGNAL =
  /\[Error:|quota|billing|rate limit|insufficient_quota|invalid_image_file|organization must be verified|bad gateway|OPENAI_IMAGE_FAILED|ToolApiError|执行失败/i;

type DialogSnapshot = {
  messageCount: number;
  artifactKeys: Set<string>;
  assistantTexts: string[];
  renderedImageCount: number;
};

type ScenarioResult =
  | {
      scenario: string;
      agentName: string;
      dialogKey: string;
      dialogId: string;
      dialogUrl: string;
      status: "image";
      artifactKeys: string[];
      reusedLatestArtifactKeys?: string[];
      renderedImageCount: number;
      assistantTexts: string[];
    }
  | {
      scenario: string;
      agentName: string;
      dialogKey: string;
      dialogId: string;
      dialogUrl: string;
      status: "validation";
      bestEffort: true;
      validation: string;
      assistantTexts: string[];
    };

type ResolvedAgent = {
  slug: (typeof AGENT_TARGETS)[number]["slug"];
  name: string;
  agentKey: string;
  record: Record<string, any>;
};

function logStep(step: string, details?: string) {
  const suffix = details ? ` ${details}` : "";
  console.log(`[verify-public-image-agents-web] ${step}${suffix}`);
}

function usage() {
  console.log(`Usage:
  bun ./scripts/verify/verifyPublicImageAgentsWeb.ts

Env:
  BASE_URL=https://us.nolo.chat
  AUTH_TOKEN=...
  BROWSER=chrome|firefox|webkit
  PW_HEADLESS=0|1
  PUBLIC_IMAGE_AGENT_SPACE_ID=...
  PUBLIC_IMAGE_GENERATOR_AGENT_KEY=agent-pub-...
  PUBLIC_IMAGE_EDITOR_AGENT_KEY=agent-pub-...
  PUBLIC_IMAGE_CONTINUOUS_AGENT_KEY=agent-pub-...
  PUBLIC_IMAGE_AGENT_SCENARIOS=generator,editor,continuous
  PUBLIC_IMAGE_AGENT_CASES=editor-single,editor-multi,editor-mask,continuous-generate,continuous-revise-1,continuous-revise-2
  PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL=https://nolo.chat/dialog-...
  PUBLIC_IMAGE_AGENT_TIMEOUT_MS=180000
  PUBLIC_IMAGE_AGENT_MIN_BALANCE=25
`);
}

function shouldRunScenario(slug: ResolvedAgent["slug"]) {
  return SELECTED_SCENARIOS.size === 0 || SELECTED_SCENARIOS.has(slug);
}

function shouldRunCase(slug: string) {
  return SELECTED_CASES.size === 0 || SELECTED_CASES.has(slug);
}

function ensureRequiredConfig() {
  if (process.argv.includes("--help") || process.argv.includes("-h")) {
    usage();
    process.exit(0);
  }
  if (!AUTH_TOKEN) {
    throw new Error("Missing auth token. Set AUTH_TOKEN (or AUTH / BENCHMARK_AUTH_TOKEN).");
  }
  if (!USER_ID) {
    throw new Error("Failed to parse userId from auth token.");
  }
}

function getBrowserType(): BrowserType {
  if (BROWSER === "firefox") return firefox;
  if (BROWSER === "webkit") return webkit;
  return chromium;
}

async function ensureBalance() {
  const userKey = `user:${USER_ID}`;
  const response = await apiGet<any>(
    `${BASE_URL}/api/v1/db/read/${encodeURIComponent(userKey)}?userId=${encodeURIComponent(USER_ID!)}`,
    AUTH_TOKEN
  );
  if (!response.ok || !response.data) {
    throw new Error(`Failed to read user balance (${response.status}) for ${userKey}`);
  }
  const balance = Number(response.data.balance ?? 0);
  if (balance < MIN_BALANCE) {
    throw new Error(
      `Insufficient balance for public image web verification. current=${balance} required>=${MIN_BALANCE}`
    );
  }
  return balance;
}

async function resolveAgents(): Promise<ResolvedAgent[]> {
  const overrides = new Map(
    AGENT_TARGETS.filter((item) => item.envKey).map((item) => [item.slug, item.envKey] as const)
  );
  const space = await readSpaceRecord(BASE_URL, AUTH_TOKEN, SPACE_ID);
  const entries = Object.entries(space.contents ?? {}).filter(([, value]) => {
    return value && typeof value === "object" && (value as any).type === ContentType.AGENT;
  });

  const cache = new Map<string, Record<string, any>>();
  const readRecordCached = async (agentKey: string) => {
    if (!cache.has(agentKey)) {
      cache.set(
        agentKey,
        await readAgentRecord({
          baseUrl: BASE_URL,
          agentKey,
          authToken: AUTH_TOKEN,
        })
      );
    }
    return cache.get(agentKey)!;
  };

  const resolved: ResolvedAgent[] = [];

  for (const target of AGENT_TARGETS) {
    const overrideKey = overrides.get(target.slug);
    if (overrideKey) {
      const record = await readRecordCached(overrideKey);
      resolved.push({ slug: target.slug, name: target.name, agentKey: overrideKey, record });
      continue;
    }

    const slotMatch = entries.find(([, value]) => {
      const title = String((value as any)?.title ?? "").trim();
      const contentKey = String((value as any)?.contentKey ?? "").trim();
      return title === target.name || contentKey === target.name;
    });

    if (slotMatch) {
      const contentKey = String((slotMatch[1] as any).contentKey ?? slotMatch[0]).trim();
      const record = await readRecordCached(contentKey);
      resolved.push({ slug: target.slug, name: target.name, agentKey: contentKey, record });
      continue;
    }

    for (const [entryKey, value] of entries) {
      const contentKey = String((value as any)?.contentKey ?? entryKey).trim();
      try {
        const record = await readRecordCached(contentKey);
        if (record?.name === target.name) {
          resolved.push({ slug: target.slug, name: target.name, agentKey: contentKey, record });
          break;
        }
      } catch {
        // ignore and continue
      }
    }
  }

  if (resolved.length !== AGENT_TARGETS.length) {
    const missing = AGENT_TARGETS.filter(
      (target) => !resolved.some((item) => item.slug === target.slug)
    ).map((item) => item.name);
    throw new Error(`Failed to resolve public image agents from shared-space truth: ${missing.join(", ")}`);
  }

  for (const item of resolved) {
    const target = AGENT_TARGETS.find((candidate) => candidate.slug === item.slug)!;
    if (item.record?.name !== target.name) {
      throw new Error(`Resolved wrong agent for ${target.name}: ${item.agentKey} -> ${item.record?.name}`);
    }
    if (item.record?.imageWorkflow !== target.expectedWorkflow) {
      throw new Error(
        `Resolved ${target.name} with unexpected workflow ${item.record?.imageWorkflow ?? "unknown"}`
      );
    }
  }

  return resolved;
}

async function openAgentDialog(page: Page, agentKey: string) {
  await page.goto(`${BASE_URL}/${encodeURIComponent(agentKey)}`, {
    waitUntil: "domcontentloaded",
    timeout: 30_000,
  });

  const activePage = await clickStartChatUntilDialog({
    currentPage: page,
    createPopupWaiter: () =>
      page.context().waitForEvent("page", { timeout: 5_000 }).catch(() => null),
    clickStartChat: () =>
      clickFirstVisibleButton(page, [/开始聊天/, /开始对话/, /开聊/, /Start Chat/i, /Chat/i]),
  });
  await activePage.locator(".message-input__textarea").first().waitFor({
    state: "visible",
    timeout: 30_000,
  });

  const dialogKey = decodeURIComponent(
    new URL(activePage.url()).pathname.split("/").filter(Boolean).at(-1) ?? ""
  );
  if (!dialogKey.startsWith("dialog-")) {
    throw new Error(`Failed to resolve dialog key from URL: ${activePage.url()}`);
  }

  return {
    page: activePage,
    dialogKey,
    dialogUrl: `${BASE_URL}/${dialogKey}`,
    dialogId: extractCustomId(dialogKey),
  };
}

function normalizeDialogUrl(raw: string) {
  if (!raw) return "";
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.startsWith("dialog-")) return `${BASE_URL}/${raw}`;
  throw new Error(`PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL must be a dialog URL or dialog key: ${raw}`);
}

async function openExistingDialog(page: Page, rawDialogUrl: string) {
  const dialogUrl = normalizeDialogUrl(rawDialogUrl);
  if (!dialogUrl) {
    throw new Error(
      "PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL is required when running continuous-revise-* without rerunning continuous-generate."
    );
  }
  await page.goto(dialogUrl, {
    waitUntil: "domcontentloaded",
    timeout: 30_000,
  });
  await page.locator(".message-input__textarea").first().waitFor({
    state: "visible",
    timeout: 30_000,
  });

  const dialogKey = decodeURIComponent(
    new URL(page.url()).pathname.split("/").filter(Boolean).at(-1) ?? ""
  );
  if (!dialogKey.startsWith("dialog-")) {
    throw new Error(`Failed to resolve dialog key from URL: ${page.url()}`);
  }

  return {
    page,
    dialogKey,
    dialogUrl: `${BASE_URL}/${dialogKey}`,
    dialogId: extractCustomId(dialogKey),
  };
}

async function clickFirstVisibleButton(page: Page, labels: Array<string | RegExp>) {
  for (const label of labels) {
    const button = page.getByRole("button", { name: label as never }).first();
    if ((await button.count()) === 0) continue;
    if (!(await button.isVisible().catch(() => false))) continue;
    await button.click().catch(async (error) => {
      const message = toErrorMessage(error);
      if (!/intercepts pointer events|Timeout/i.test(message)) throw error;
      await button.click({ force: true });
    });
    return;
  }
  throw new Error(`Could not find visible button for ${labels.map(String).join(", ")}`);
}

async function uploadImages(
  page: Page,
  files: Array<{ name: string; mimeType: string; buffer: Buffer }>
) {
  const previewItems = page.locator(".attachments-preview .image-item");
  const beforeCount = await previewItems.count();
  await page.locator('input[type="file"]').setInputFiles(files);
  await page.waitForFunction(
    ({ selector, expected }) => document.querySelectorAll(selector).length >= expected,
    { selector: ".attachments-preview .image-item", expected: beforeCount + files.length },
    { timeout: 30_000 }
  );
  await page.waitForFunction(
    () =>
      !document.querySelector(".message-input--processing") &&
      !document.querySelector(".send-button.send-mode:disabled"),
    undefined,
    { timeout: 60_000 }
  );
}

async function sendPrompt(page: Page, prompt: string, dialogId: string) {
  const beforeMessages = await readDialogMessages(dialogId);
  const textarea = page.locator(".message-input__textarea").first();
  await textarea.fill(prompt);
  await page.waitForFunction(
    () => !document.querySelector(".send-button.send-mode:disabled"),
    undefined,
    { timeout: 60_000 }
  );
  await textarea.press("Enter");
  await page.waitForFunction(
    async ({ baseUrl, authToken, dialogId, beforeCount }) => {
      const response = await fetch(`${baseUrl}/rpc/getConvMsgs`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${authToken}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ dialogId, limit: 60 }),
      });
      if (!response.ok) return false;
      const messages = await response.json().catch(() => []);
      return Array.isArray(messages) && messages.length > beforeCount;
    },
    {
      baseUrl: BASE_URL,
      authToken: AUTH_TOKEN,
      dialogId,
      beforeCount: beforeMessages.length,
    },
    { timeout: 30_000 }
  );
}

async function readDialogMessages(dialogId: string): Promise<DialogMessage[]> {
  const response = await fetch(`${BASE_URL}/rpc/getConvMsgs`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${AUTH_TOKEN}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ dialogId, limit: 60 }),
  });
  const data = await response.json().catch(() => []);
  if (!response.ok || !Array.isArray(data)) {
    throw new Error(`Failed to read dialog messages (${response.status}): ${JSON.stringify(data)}`);
  }
  return data as DialogMessage[];
}

async function assertCarryForwardForScenario(args: {
  dialogId: string;
  dialogUrl: string;
  scenario: string;
  expectedArtifactKeys: string[];
  forbiddenArtifactKeys?: string[];
}) {
  const messages = await readDialogMessages(args.dialogId);
  return verifyScenarioCarryForward({
    messages,
    scenario: args.scenario,
    expectedArtifactKeys: args.expectedArtifactKeys,
    forbiddenArtifactKeys: args.forbiddenArtifactKeys,
    userId: USER_ID,
    dialogUrl: args.dialogUrl,
  }).reusedLatestArtifactKeys;
}

async function readDialogSnapshot(page: Page, dialogId: string): Promise<DialogSnapshot> {
  const messages = await readDialogMessages(dialogId);
  const artifactKeys = new Set(collectDialogArtifactKeys(messages, USER_ID));
  const assistantTexts: string[] = [];

  for (const message of messages) {
    if (message.role === "assistant") {
      collectStrings(message.content, assistantTexts);
    }
  }

  return {
    messageCount: messages.length,
    artifactKeys,
    assistantTexts,
    renderedImageCount: await page.locator(".g-img-card img").count(),
  };
}

async function waitForRenderedImageCount(page: Page, expectedMinimum: number) {
  await page.waitForFunction(
    ({ selector, expectedMinimum }) =>
      document.querySelectorAll(selector).length >= expectedMinimum,
    { selector: ".g-img-card img", expectedMinimum },
    { timeout: TIMEOUT_MS }
  );
}

async function verifyPersistedImageKeys(keys: string[]) {
  const metadata: Array<{ key: string; mimeType?: string; filePath?: string }> = [];
  for (const key of keys) {
    const record = await readDbRecord(BASE_URL, AUTH_TOKEN, key).catch(() => null);
    if (!record) continue;
    metadata.push({
      key,
      mimeType: typeof record.mimeType === "string" ? record.mimeType : undefined,
      filePath: typeof record.filePath === "string" ? record.filePath : undefined,
    });
  }
  const hasRenderedImageFile = metadata.some((item) =>
    (item.mimeType ?? "").toLowerCase().startsWith("image/")
  );
  if (!hasRenderedImageFile) {
    throw new Error(`No persisted image file metadata found for generated artifacts: ${keys.join(", ")}`);
  }
}

function pickValidationSignal(texts: string[]) {
  return texts
    .map((text) => text.trim())
    .find((text) => text && VALIDATION_SIGNAL.test(text));
}

function pickUpstreamErrorSignal(texts: string[]) {
  return texts
    .map((text) => text.trim())
    .find((text) => text && UPSTREAM_ERROR_SIGNAL.test(text));
}

async function waitForTurnResult(args: {
  page: Page;
  dialogId: string;
  dialogKey: string;
  dialogUrl?: string;
  scenario: string;
  agentName: string;
  before: DialogSnapshot;
  bestEffort?: boolean;
}): Promise<ScenarioResult> {
  const startedAt = Date.now();
  let lastAssistantTexts = args.before.assistantTexts;

  while (Date.now() - startedAt < TIMEOUT_MS) {
    const snapshot = await readDialogSnapshot(args.page, args.dialogId);
    lastAssistantTexts = snapshot.assistantTexts;

    const newArtifactKeys = Array.from(snapshot.artifactKeys).filter(
      (key) => !args.before.artifactKeys.has(key)
    );
    if (newArtifactKeys.length > 0) {
      await verifyPersistedImageKeys(newArtifactKeys);
      await waitForRenderedImageCount(
        args.page,
        Math.max(args.before.renderedImageCount + 1, 1)
      );
      return {
        scenario: args.scenario,
        agentName: args.agentName,
        dialogKey: args.dialogKey,
        dialogId: args.dialogId,
        dialogUrl: args.dialogUrl ?? `${BASE_URL}/${args.dialogKey}`,
        status: "image",
        artifactKeys: newArtifactKeys,
        renderedImageCount: await args.page.locator(".g-img-card img").count(),
        assistantTexts: snapshot.assistantTexts.slice(-4),
      };
    }

    const assistantDelta =
      snapshot.messageCount > args.before.messageCount
        ? snapshot.assistantTexts.slice(Math.max(args.before.assistantTexts.length - 1, 0))
        : snapshot.assistantTexts;
    const upstreamError = pickUpstreamErrorSignal(assistantDelta);
    if (upstreamError) {
      const dialogUrl = args.dialogUrl ?? `${BASE_URL}/${args.dialogKey}`;
      throw new Error(
        `[${args.scenario}] upstream image provider error for ${args.agentName}. Dialog: ${dialogUrl}. error=${JSON.stringify(
          upstreamError
        )}`
      );
    }
    const validation = pickValidationSignal(assistantDelta);
    if (args.bestEffort && validation) {
      return {
        scenario: args.scenario,
        agentName: args.agentName,
        dialogKey: args.dialogKey,
        dialogId: args.dialogId,
        dialogUrl: args.dialogUrl ?? `${BASE_URL}/${args.dialogKey}`,
        status: "validation",
        bestEffort: true,
        validation,
        assistantTexts: assistantDelta.slice(-4),
      };
    }

    await Bun.sleep(2_000);
  }

  const suffix = args.bestEffort
    ? "Expected an image or a clear validation/error path rather than silent failure."
    : "Expected a generated image artifact.";
  const dialogUrl = args.dialogUrl ?? `${BASE_URL}/${args.dialogKey}`;
  throw new Error(
    `[${args.scenario}] timed out for ${args.agentName}. Dialog: ${dialogUrl}. ${suffix} assistant=${JSON.stringify(
      lastAssistantTexts.slice(-4)
    )}`
  );
}

async function runGeneratorScenario(agent: ResolvedAgent, page: Page) {
  const opened = await openAgentDialog(page, agent.agentKey);
  const before = await readDialogSnapshot(opened.page, opened.dialogId);
  await sendPrompt(
    opened.page,
    `generator-text-to-image ${Date.now().toString(36)} 生成一张极简海报风插画：夜空、单个发光热气球、不要文字。`,
    opened.dialogId
  );
  return waitForTurnResult({
    page: opened.page,
    dialogId: opened.dialogId,
    dialogKey: opened.dialogKey,
    dialogUrl: opened.dialogUrl,
    scenario: "generator-text-to-image",
    agentName: agent.name,
    before,
  });
}

async function runEditorScenario(agent: ResolvedAgent, page: Page) {
  const results: ScenarioResult[] = [];

  if (shouldRunCase("editor-single")) {
    const single = await openAgentDialog(page, agent.agentKey);
    await uploadImages(single.page, [
      {
        name: `editor-single-${Date.now().toString(36)}.png`,
        mimeType: "image/png",
        buffer: PNG_RED,
      },
    ]);
    const beforeSingle = await readDialogSnapshot(single.page, single.dialogId);
    await sendPrompt(
      single.page,
      "editor-single-image-edit 把这张图改成更亮、更柔和的浅色卡通风，不要加文字。",
      single.dialogId
    );
    results.push(
      await waitForTurnResult({
        page: single.page,
        dialogId: single.dialogId,
        dialogKey: single.dialogKey,
        dialogUrl: single.dialogUrl,
        scenario: "editor-single-image-edit",
        agentName: agent.name,
        before: beforeSingle,
      })
    );
  }

  if (shouldRunCase("editor-multi")) {
    const multi = await page.context().newPage();
    await installPlaywrightAuthBootstrap(
      multi,
      buildPlaywrightAuthBootstrap(AUTH_TOKEN, {
        currentServer: BASE_URL,
        syncServers: [BASE_URL],
      })
    );
    const multiDialog = await openAgentDialog(multi, agent.agentKey);
    await uploadImages(multiDialog.page, [
      {
        name: `editor-multi-base-${Date.now().toString(36)}.png`,
        mimeType: "image/png",
        buffer: PNG_RED,
      },
      {
        name: `editor-multi-ref-${Date.now().toString(36)}.png`,
        mimeType: "image/png",
        buffer: PNG_GREEN,
      },
    ]);
    const beforeMulti = await readDialogSnapshot(multiDialog.page, multiDialog.dialogId);
    await sendPrompt(
      multiDialog.page,
      "editor-multi-image-edit 参考第二张图的配色和氛围，重绘第一张图，保持主体但让画面更像海报草图。",
      multiDialog.dialogId
    );
    results.push(
      await waitForTurnResult({
        page: multiDialog.page,
        dialogId: multiDialog.dialogId,
        dialogKey: multiDialog.dialogKey,
        dialogUrl: multiDialog.dialogUrl,
        scenario: "editor-multi-image-edit",
        agentName: agent.name,
        before: beforeMulti,
      })
    );
  }

  if (shouldRunCase("editor-mask")) {
    const mask = await page.context().newPage();
    await installPlaywrightAuthBootstrap(
      mask,
      buildPlaywrightAuthBootstrap(AUTH_TOKEN, {
        currentServer: BASE_URL,
        syncServers: [BASE_URL],
      })
    );
    const maskDialog = await openAgentDialog(mask, agent.agentKey);
    await uploadImages(maskDialog.page, [
      {
        name: `editor-mask-base-${Date.now().toString(36)}.png`,
        mimeType: "image/png",
        buffer: PNG_BLACK,
      },
      {
        name: `editor-mask-mask-${Date.now().toString(36)}.png`,
        mimeType: "image/png",
        buffer: PNG_MASK,
      },
    ]);
    const beforeMask = await readDialogSnapshot(maskDialog.page, maskDialog.dialogId);
    await sendPrompt(
      maskDialog.page,
      [
        "editor-mask-validation",
        "把第一张当原图，第二张当 mask。",
        "如果当前 web chat / tooling 不能稳定表达 mask，请明确返回 validation/error，禁止 silent failure。",
      ].join(" "),
      maskDialog.dialogId
    );
    results.push(
      await waitForTurnResult({
        page: maskDialog.page,
        dialogId: maskDialog.dialogId,
        dialogKey: maskDialog.dialogKey,
        dialogUrl: maskDialog.dialogUrl,
        scenario: "editor-mask-validation",
        agentName: agent.name,
        before: beforeMask,
        bestEffort: true,
      })
    );
  }

  return results;
}

async function runContinuousScenario(agent: ResolvedAgent, page: Page) {
  const runsAllContinuousCases = SELECTED_CASES.size === 0;
  const shouldRunGenerate = runsAllContinuousCases || shouldRunCase("continuous-generate");
  const shouldRunRevise1 = runsAllContinuousCases || shouldRunCase("continuous-revise-1");
  const shouldRunRevise2 = runsAllContinuousCases || shouldRunCase("continuous-revise-2");
  const opened =
    shouldRunGenerate || !PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL
      ? await openAgentDialog(page, agent.agentKey)
      : await openExistingDialog(page, PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL);
  const results: ScenarioResult[] = [];
  let generated: Extract<ScenarioResult, { status: "image" }> | null = null;
  let revise1: Extract<ScenarioResult, { status: "image" }> | null = null;

  if (shouldRunGenerate) {
    const beforeGenerate = await readDialogSnapshot(opened.page, opened.dialogId);
    await sendPrompt(
      opened.page,
      "continuous-generate 先出一张简洁的宇航员贴纸风插画，白底、单主体、不要文字。",
      opened.dialogId
    );
    const result = await waitForTurnResult({
      page: opened.page,
      dialogId: opened.dialogId,
      dialogKey: opened.dialogKey,
      dialogUrl: opened.dialogUrl,
      scenario: "continuous-generate",
      agentName: agent.name,
      before: beforeGenerate,
    });
    results.push(result);
    if (result.status !== "image") {
      throw new Error("continuous-generate must yield an image result.");
    }
    generated = result;
  }

  if (shouldRunRevise1) {
    const result = await runContinuousReviseStep({
      opened,
      agentName: agent.name,
      scenario: "continuous-revise-1",
      prompt: "continuous-revise-1 基于上一版继续改：把宇航员头盔做得更大一点，背景改成淡紫色。",
      expectedArtifactKeys: generated?.artifactKeys,
    });
    revise1 = result;
    results.push(result);
  }

  if (shouldRunRevise2) {
    results.push(
      await runContinuousReviseStep({
        opened,
        agentName: agent.name,
        scenario: "continuous-revise-2",
        prompt: "continuous-revise-2 再基于最新一版继续改：加一颗小星星徽章，整体更像最终定稿。",
        expectedArtifactKeys: revise1?.artifactKeys,
      })
    );
  }

  return results;
}

async function runContinuousReviseStep(args: {
  opened: Awaited<ReturnType<typeof openAgentDialog>>;
  agentName: string;
  scenario: "continuous-revise-1" | "continuous-revise-2";
  prompt: string;
  expectedArtifactKeys?: string[];
}) {
  const before = await readDialogSnapshot(args.opened.page, args.opened.dialogId);
  const expectedKeys = args.expectedArtifactKeys ?? latestArtifactKeys(before);
  await sendPrompt(args.opened.page, args.prompt, args.opened.dialogId);
  const result = await waitForTurnResult({
    page: args.opened.page,
    dialogId: args.opened.dialogId,
    dialogKey: args.opened.dialogKey,
    dialogUrl: args.opened.dialogUrl,
    scenario: args.scenario,
    agentName: args.agentName,
    before,
  });
  if (result.status !== "image") {
    throw new Error(`${args.scenario} must yield an image result.`);
  }
  return {
    ...result,
    reusedLatestArtifactKeys: await assertCarryForwardForScenario({
      dialogId: args.opened.dialogId,
      dialogUrl: args.opened.dialogUrl,
      scenario: args.scenario,
      expectedArtifactKeys: expectedKeys,
      forbiddenArtifactKeys: previousArtifactKeys(before, expectedKeys),
    }),
  };
}

function latestArtifactKeys(snapshot: DialogSnapshot) {
  const keys = Array.from(snapshot.artifactKeys);
  const latest = keys.at(-1);
  if (!latest) {
    throw new Error("No prior image artifact found. Run continuous-generate first or set PUBLIC_IMAGE_CONTINUOUS_DIALOG_URL to a dialog with an image.");
  }
  return [latest];
}

function previousArtifactKeys(snapshot: DialogSnapshot, latestKeys: string[]) {
  return Array.from(snapshot.artifactKeys).filter((key) => !latestKeys.includes(key));
}

async function main() {
  ensureRequiredConfig();
  const balance = await ensureBalance();
  const agents = await resolveAgents();
  const browser = await launchBrowserProbe(getBrowserType(), {
    headless: HEADLESS,
    ...(BROWSER === "chrome" ? { channel: "chrome" } : {}),
  });

  try {
    const context = await browser.newContext({ viewport: { width: 1440, height: 960 } });
    const bootstrap = buildPlaywrightAuthBootstrap(AUTH_TOKEN, {
      currentServer: BASE_URL,
      syncServers: [BASE_URL],
    });
    const results: ScenarioResult[] = [];

    if (shouldRunScenario("generator")) {
      const generatorPage = await context.newPage();
      await installPlaywrightAuthBootstrap(generatorPage, bootstrap);
      const agent = agents.find((item) => item.slug === "generator")!;
      logStep("generator", agent.agentKey);
      results.push(await runGeneratorScenario(agent, generatorPage));
    }

    if (shouldRunScenario("editor")) {
      const editorPage = await context.newPage();
      await installPlaywrightAuthBootstrap(editorPage, bootstrap);
      const agent = agents.find((item) => item.slug === "editor")!;
      logStep("editor", agent.agentKey);
      results.push(...(await runEditorScenario(agent, editorPage)));
    }

    if (shouldRunScenario("continuous")) {
      const continuousPage = await context.newPage();
      await installPlaywrightAuthBootstrap(continuousPage, bootstrap);
      const agent = agents.find((item) => item.slug === "continuous")!;
      logStep("continuous", agent.agentKey);
      results.push(...(await runContinuousScenario(agent, continuousPage)));
    }

    console.log(
      JSON.stringify(
        {
          ok: true,
          baseUrl: BASE_URL,
          browser: BROWSER,
          headless: HEADLESS,
          balance,
          spaceId: SPACE_ID,
          agents: agents.map((item) => ({
            slug: item.slug,
            name: item.name,
            agentKey: item.agentKey,
            imageWorkflow: item.record?.imageWorkflow ?? null,
          })),
          selectedScenarios: Array.from(SELECTED_SCENARIOS),
          selectedCases: Array.from(SELECTED_CASES),
          results,
          notes: [
            "Multi-image edit is a required-success path: it must yield a generated image artifact, not a soft validation pass.",
            "Mask branch is bestEffort: it must yield either a generated image or a clear validation/error path, never silent failure.",
            "Continuous carry is verified by requiring each revise turn to reference the immediately prior artifact keys without older carry-forward leakage.",
          ],
        },
        null,
        2
      )
    );
  } finally {
    await browser.close();
  }
}

main().catch((error) => {
  console.error("[verify-public-image-agents-web] failed", error);
  process.exitCode = 1;
});
